//! Compact portable schematic codec. States are stored as registry strings,
//! never process-local IDs, so files survive server restarts.
use std::collections::HashMap;
use crate::clipboard::Clipboard;
use crate::math::BlockVector3;
use crate::registry::BlockStateRegistry;

const MAGIC:&[u8;8]=b"FAWEBIM1";
pub fn encode(clip:&Clipboard,reg:&dyn BlockStateRegistry)->Result<Vec<u8>,String>{let mut palette=Vec::<String>::new();let mut ids=HashMap::<i32,u32>::new();let mut cells=Vec::new();clip.for_each(|x,y,z,state|{let idx=*ids.entry(state).or_insert_with(||{let i=palette.len()as u32;palette.push(reg.describe(state));i});cells.push((x,y,z,idx));});let mut out=MAGIC.to_vec();for v in [clip.size().x,clip.size().y,clip.size().z,clip.origin().x,clip.origin().y,clip.origin().z]{out.extend_from_slice(&v.to_le_bytes());}put_u32(&mut out,palette.len()as u32);for s in palette{put_u32(&mut out,s.len()as u32);out.extend_from_slice(s.as_bytes());}put_u32(&mut out,cells.len()as u32);for(x,y,z,p)in cells{for v in [x,y,z]{out.extend_from_slice(&v.to_le_bytes());}put_u32(&mut out,p);}if out.len()>64<<20{return Err("schematic exceeds 64 MiB".into());}Ok(out)}
pub fn decode(data:&[u8],reg:&dyn BlockStateRegistry)->Result<Clipboard,String>{let mut r=Reader{data,pos:0};if r.take(8)?!=MAGIC{return Err("not a FAWE-BIM schematic".into());}let size=BlockVector3::at(r.i32()?,r.i32()?,r.i32()?);let origin=BlockVector3::at(r.i32()?,r.i32()?,r.i32()?);if size.x<=0||size.y<=0||size.z<=0{return Err("invalid schematic dimensions".into());}let volume=(size.x as usize).checked_mul(size.y as usize).and_then(|v|v.checked_mul(size.z as usize)).ok_or("schematic is too large")?;if volume>2_000_000{return Err("schematic exceeds the block limit".into());}let pn=r.u32()? as usize;if pn>65536{return Err("schematic palette is too large".into());}let mut palette=Vec::with_capacity(pn);for _ in 0..pn{let n=r.u32()? as usize;let s=std::str::from_utf8(r.take(n)?).map_err(|_|"invalid UTF-8 state")?;let state=reg.parse(s);if state<0{return Err(format!("unknown block state '{s}'"));}palette.push(state);}let count=r.u32()? as usize;if count>volume{return Err("too many schematic cells".into());}let mut blocks=vec![-1;volume];for _ in 0..count{let(x,y,z,p)=(r.i32()?,r.i32()?,r.i32()?,r.u32()? as usize);if x<0||y<0||z<0||x>=size.x||y>=size.y||z>=size.z||p>=palette.len(){return Err("invalid schematic cell".into());}let i=(y*size.z*size.x+z*size.x+x)as usize;blocks[i]=palette[p];}if r.pos!=data.len(){return Err("trailing schematic data".into());}Ok(Clipboard::from_parts(size,origin,blocks))}
fn put_u32(out:&mut Vec<u8>,v:u32){out.extend_from_slice(&v.to_le_bytes());}struct Reader<'a>{data:&'a[u8],pos:usize}impl<'a>Reader<'a>{fn take(&mut self,n:usize)->Result<&'a[u8],String>{let end=self.pos.checked_add(n).ok_or("truncated schematic")?;let s=self.data.get(self.pos..end).ok_or("truncated schematic")?;self.pos=end;Ok(s)}fn u32(&mut self)->Result<u32,String>{Ok(u32::from_le_bytes(self.take(4)?.try_into().unwrap()))}fn i32(&mut self)->Result<i32,String>{Ok(i32::from_le_bytes(self.take(4)?.try_into().unwrap()))}}
#[cfg(test)]mod tests{use super::*;use crate::region::{CuboidRegion,RegionShape};use crate::world::{Extent,InMemoryWorld};use crate::registry::InMemoryBlockRegistry;#[test]fn round_trip_is_portable_and_rejects_damage(){let reg=InMemoryBlockRegistry::with_vanilla_subset();let mut w=InMemoryWorld::default();w.set_block(2,3,4,reg.parse("stone"));let mut region=RegionShape::Cuboid(CuboidRegion::new(BlockVector3::at(2,3,4),BlockVector3::at(2,3,4)));let c=Clipboard::capture(&w,&mut region);let bytes=encode(&c,&reg).unwrap();let d=decode(&bytes,&reg).unwrap();assert_eq!(d.origin(),c.origin());assert_eq!(d.get(0,0,0),reg.parse("stone"));assert!(decode(&bytes[..10],&reg).is_err());}}
